// Fixed-format daily report, no LLM. "Needs review" mirrors toShipment() in lib/firestore.ts,
// so the numbers match the web app's dashboard: change both together.
const TZ = 'Asia/Kuala_Lumpur'; // same as the workflow's timezone setting, which fires the 8am trigger
const LABELS = { 'Document-Comparison Request': 'SI BL Comparison', 'New SI Request': 'SI Request', 'Invoice Queries': 'Invoice', 'General Messages': 'General', Spam: 'Spam' };
const val = f => f?.stringValue ?? f?.timestampValue ?? f?.booleanValue;
const label = f => LABELS[val(f.classification)] ?? 'Spam'; // same fallback as the app
const needsReview = f =>
  !!val(f.missing_attachments_warning) || !!val(f.classification_error) || !!f.last_ingestion_error?.mapValue ||
  (!f.attachments?.arrayValue?.values?.length && val(f.classification) === 'Document-Comparison Request') ||
  val(f.human_review_required) === true || ['flagged', 'needs_review', 'incomplete'].includes(val(f.status));
const count = (list, test) => list.filter(test).length;

// runQuery returns one item per document (a bare {readTime} when there are none).
const emails = $input.all().filter(i => i.json.document).map(i => i.json.document.fields ?? {});
const since = Date.now() - 24 * 60 * 60 * 1000;
const recent = emails.filter(f => Date.parse(val(f.classified_at)) >= since);
const failed = Number($('Failed Ingestion').first().json.result?.aggregateFields?.failed?.integerValue ?? 0);

const text = [
  'Shiptuationship daily report',
  new Date().toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric', timeZone: TZ }),
  '',
  'Last 24 hours',
  `New emails: ${recent.length}`,
  ...Object.values(LABELS).map(l => `• ${l}: ${count(recent, f => label(f) === l)}`),
  `Comparisons cleared: ${count(recent, f => val(f.status) === 'cleared' && !needsReview(f))}`,
  `Sent to human review: ${count(recent, needsReview)}`,
  '',
  'Open now',
  `Needs human review: ${count(emails, needsReview)}`,
  `Unread: ${count(emails, f => f.read_status?.mapValue?.fields?.is_read?.booleanValue !== true)}`,
  `Failed ingestion: ${failed}`,
  '',
  'https://shiptuationship.vercel.app/dashboard',
].join('\n');
return [{ json: { text } }];
